import { ChangeDetectionStrategy, Component, booleanAttribute, input, model } from '@angular/core';

@Component({
  selector: 'aevko-collapsible',
  standalone: true,
  templateUrl: './collapsible.component.html',
  styleUrl: './collapsible.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { 'data-slot': 'collapsible' },
})
export class AevkoCollapsible {
  readonly label = input.required<string>();
  readonly open = model(false);
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly panelId = input('aevko-collapsible-panel');

  protected toggle(): void {
    if (!this.disabled()) this.open.update((value) => !value);
  }
}

:host {
  border-block: 1px solid var(--aevko-border, #e4e4e7);
  display: block;
}
button {
  align-items: center;
  background: transparent;
  border: 0;
  color: inherit;
  cursor: pointer;
  display: flex;
  font: 500 0.875rem/1.5 var(--aevko-font-sans, sans-serif);
  justify-content: space-between;
  min-height: 2.75rem;
  padding: 0.75rem 0;
  text-align: start;
  width: 100%;
}
button:focus-visible {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
.indicator {
  align-items: center;
  display: inline-flex;
  flex: none;
  line-height: 0;
  transition: transform 120ms ease;
}
.indicator.open {
  transform: rotate(90deg);
}
.indicator svg {
  height: 1rem;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
  width: 1rem;
}
.indicator:has(> :not(.fallback-icon)) > .fallback-icon {
  display: none;
}
.panel {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  visibility: hidden;
  transition:
    grid-template-rows 220ms cubic-bezier(0.2, 0, 0, 1),
    opacity 180ms ease,
    visibility 0s 220ms;
}
.panel[data-state='open'] {
  grid-template-rows: 1fr;
  opacity: 1;
  visibility: visible;
  transition-delay: 0s;
}
.content-clip {
  min-height: 0;
  overflow: hidden;
}
.content {
  padding-block-end: 1rem;
  font-size: 0.875rem;
  line-height: 1.7;
}
button:hover:not(:disabled) > span:first-child {
  text-decoration: underline;
  text-underline-offset: 4px;
}
@media (prefers-reduced-motion: reduce) {
  .indicator,
  .panel {
    transition: none;
  }
}

[hidden] {
  display: none;
}
